const BULAN_ID = ['JANUARI','FEBRUARI','MARET','APRIL','MEI','JUNI','JULI','AGUSTUS','SEPTEMBER','OKTOBER','NOVEMBER','DESEMBER'];

function namaBulanDariTanggal(tglStr){
  if(!tglStr) return '';
  const d = new Date(tglStr);
  if(isNaN(d.getTime())) return '';
  return BULAN_ID[d.getMonth()];
}

const OPTIONAL_PHOTO_KEYS = new Set([
  'wifi_analyzer_ap1', 'wifi_analyzer_ap2', 'wifi_analyzer_ap1_baktiaksi', 'wifi_analyzer_ap2_baktiaksi'
]);

function validateRequired(){
  const f = state.fields;
  if(!f.nama_lokasi || !f.nama_lokasi.trim()) return 'Nama Lokasi wajib diisi.';
  if(!f.site_id || !f.site_id.trim()) return 'Site ID wajib diisi.';
  if(!f.tanggal) return 'Tanggal Kunjungan wajib diisi.';

  const missingDevices = [];
  DEVICE_ITEMS.forEach(it=>{
    const before = state.fields['dev_sn_before_'+it.key];
    const after = state.fields['dev_sn_after_'+it.key];
    if(!before || !before.trim() || !after || !after.trim()) missingDevices.push(it.label);
  });
  if(missingDevices.length){
    return 'Bagian "Perangkat Terpasang" wajib diisi lengkap (S/N Sebelum & Sesudah).\nBelum diisi: ' + missingDevices.join(', ');
  }

  const missingPhotos = [];
  PHOTO_ITEMS.forEach(([key,label])=>{
    if(OPTIONAL_PHOTO_KEYS.has(key)) return;
    if(!state.photos[key] || !state.photos[key].blob) missingPhotos.push(label);
  });
  if(missingPhotos.length){
    return 'Bagian "Dokumentasi Foto" wajib diisi semua ('+missingPhotos.length+' foto belum diisi).\nBelum diisi: '
      + missingPhotos.slice(0,6).join(', ') + (missingPhotos.length>6 ? ', dan lainnya.' : '.');
  }

  return null;
}

function setProgress(pct){
  const wrap = document.getElementById('progressWrap');
  wrap.style.display = pct>0 && pct<100 ? 'block' : (pct>=100 ? 'none' : 'none');
  document.getElementById('progressBar').style.width = pct+'%';
}

const BULAN_CAP = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];

function bulanTahunFolderName(){
  const tglStr = state.fields.tanggal;
  if(!tglStr) return '';
  const d = new Date(tglStr);
  if(isNaN(d.getTime())) return '';
  return `${BULAN_CAP[d.getMonth()]} ${d.getFullYear()}`;
}

function kategoriFolderName(){
  const v = (state.fields.kategori_bmn || '').trim().toUpperCase();
  if(!v || v === '— PILIH —') return '';
  return v;
}

function fileBaseName(){
  const f = state.fields;
  return `LAPORAN KUNJUNGAN ${f.tanggal || ''} ${(f.nama_lokasi||'').toUpperCase()}`.trim();
}

function folderName(){
  const f = state.fields;
  const bulan = namaBulanDariTanggal(f.tanggal);
  return `LAPORAN KUNJUNGAN ${bulan} ${(f.nama_lokasi||'').toUpperCase()}`.trim();
}

async function downloadLocalCopy(){
  const err = validateRequired();
  if(err){ alert(err); return; }
  const btn = document.getElementById('submitBtn');
  try{
    log('Membuat file Word...');
    const doc = await buildDocx();
    const blob = await Packer.toBlob(doc);
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = fileBaseName()+'.docx';
    a.click();
    log('File tersimpan ke perangkat ✓');
  }catch(e){
    log('Gagal membuat file: '+e.message);
    alert('Gagal membuat file: '+e.message);
  }
}

async function submitReport(){
  const err = validateRequired();
  if(err){ alert(err); return; }
  const btn = document.getElementById('submitBtn');
  const scriptUrl = getCfg(CFG_KEYS.appsScriptUrl, DEFAULT_APPS_SCRIPT_URL);
  if(!scriptUrl || scriptUrl.indexOf('GANTI_DENGAN') === 0){
    alert('URL Apps Script belum diatur. Buka Pengaturan.'); return;
  }

  btn.disabled = true;
  const origText = btn.textContent;
  document.getElementById('statusLog').textContent = '';
  document.getElementById('statusLog').classList.add('show');

  try{
    btn.textContent = 'Menyusun laporan...';
    setProgress(20);
    log('Menyusun dokumen Word...');
    const doc = await buildDocx();
    const blob = await Packer.toBlob(doc);

    btn.textContent = 'Menyiapkan data...';
    setProgress(45);
    const fileBase64 = await blobToBase64(blob);
    const bulanTahun = bulanTahunFolderName();
    const kategori = kategoriFolderName();
    const folderLokasi = folderName();
    const finalName = fileBaseName()+'.docx';

    log('Mengirim ke server (upload Drive + update spreadsheet)...');
    btn.textContent = 'Mengirim...';
    setProgress(65);

    const result = await sendToAppsScript({
      fileName: finalName,
      fileBase64: fileBase64,
      bulanTahun: bulanTahun,
      kategori: kategori,
      folderLokasi: folderLokasi,
      siteId: state.fields.site_id,
      tanggal: state.fields.tanggal,
    });

    setProgress(100);

    if(result.drive){
      log('Upload ke Drive berhasil ✓');
      if(result.drive.url) log('Link: '+result.drive.url);
    } else {
      log('⚠ Upload ke Drive GAGAL: '+(result.driveError||'tidak diketahui'));
    }

    if(result.sheet && result.sheet.updated){
      log('Update spreadsheet berhasil ✓ (kolom: '+result.sheet.label+')');
    } else if(result.sheet){
      log('⚠ Spreadsheet TIDAK diupdate: '+(result.sheet.reason||'tidak diketahui'));
    } else if(result.sheetError){
      log('⚠ Update spreadsheet GAGAL: '+result.sheetError);
    }

    const driveOk = !!result.drive;
    const sheetOk = !!(result.sheet && result.sheet.updated);
    if(driveOk && sheetOk){
      alert('Laporan berhasil diupload ke Drive dan spreadsheet sudah terupdate!\nFolder: '+[bulanTahun, kategori, folderLokasi].filter(Boolean).join(' / '));
    } else if(driveOk && !sheetOk){
      alert('File berhasil diupload ke Drive, TAPI update spreadsheet gagal.\nCek kotak log di bawah, mohon update manual kolom tanggal PM untuk site ini.');
    } else if(!driveOk && sheetOk){
      alert('Spreadsheet berhasil diupdate, TAPI upload file ke Drive gagal.\nCoba tombol "Simpan ke HP/Laptop" lalu upload manual filenya.');
    } else {
      alert('Gagal total (Drive maupun spreadsheet). Cek kotak log di bawah.\nCoba tombol "Simpan ke HP/Laptop" sebagai cadangan.');
    }
  }catch(e){
    log('ERROR: '+e.message);
    alert('Gagal mengirim: '+e.message+'\n\nCoba tombol "Simpan ke HP/Laptop" sebagai cadangan.');
  }finally{
    btn.disabled = false;
    btn.textContent = origText;
    setTimeout(()=>setProgress(0), 1500);
  }
}
